observation.query:
SELECT DISTINCT ?graph ?subject ?predicate ?object
WHERE {
  VALUES ?graph {
    <urn:graphragprov:unit:u_50c7c1016e220d74>
    <urn:graphragprov:unit:u_79aadb8bf764b471>
    <urn:graphragprov:unit:u_d7d2897adca05f10>
    <urn:graphragprov:unit:u_eeb15ee43d250059>
  }
  GRAPH ?graph {
    ?subject ?predicate ?object .
    FILTER(isIRI(?subject))
  }
}
ORDER BY ?graph ?subject ?predicate ?object
